/** Real placed supports, actual accepted vanilla movement packets and native retained inspection/receipts. */
final class MineAccessRuntime {
 static final BlockPos ROOT=new BlockPos(32,16,-32);static final int N=20;
 static BlockPos at(int n){return ROOT.south(n).below(n);}
 static void run(GameTestHelper h)throws Exception{
  var level=h.getLevel();var server=level.getServer();server.tickRateManager().setTickRate(20);var mine=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().toString().equals(Profession.MINER.buildingId())).findFirst().orElseThrow();var p=server.getPlayerList().getPlayer(mine.owner());h.assertTrue(p!=null,"Original actual500XP Miner attends");server.getPlayerList().deop(p.getGameProfile());var track=CommerceService.store(server).professions(p.getUUID()).track(Profession.MINER);
  if(track.completedQuestIds().contains(MineInspection.FINAL)){h.assertTrue(track.xp()==800&&track.completedQuestIds().size()==8&&CommerceService.store(server).professions(p.getUUID()).rank(Profession.MINER,ProfessionService.quests())==ProfessionRank.JOURNEYMAN,"Third JVM retains all8/800XP/Journeyman");for(int n=0;n<N;n++)level.getChunk(at(n));h.assertTrue(MineAccessSavedData.get(server).evidence().route(p.getUUID()).orElseThrow().cells().size()>=16,"Actual completed retained descent survives restart");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("MINE_ACCESS_RESTART_PASSED: native retained route/completed true walk/all8earned800XP/Journeyman/original coal-iron-copper/receipt/Mine-Doran records restored");h.succeed();return;}
  h.assertTrue(track.xp()==500&&track.completedQuestIds().size()==5,"Start from five actually earned ore/masonry/service proofs only");for(int x=(ROOT.getX()-8)>>4;x<=(ROOT.getX()+8)>>4;x++)for(int z=(ROOT.getZ()-6)>>4;z<=(ROOT.getZ()+N+3)>>4;z++){var pos=new BlockPos(x*16,ROOT.getY(),z*16);level.getChunk(x,z);ClaimRuntimeTests.ftbUnclaim(level,pos);ClaimRuntimeTests.opacUnclaim(level,pos);ClaimRuntimeTests.ftbClaim(p,pos);ClaimRuntimeTests.opacClaim(level,p.getUUID(),pos);}
  if(java.nio.file.Files.exists(server.getWorldPath(LevelResource.ROOT).resolve("mine-access-corrupt.txt"))){corrupt(h,p);return;}
  if(java.nio.file.Files.exists(server.getWorldPath(LevelResource.ROOT).resolve("mine-access-built.txt"))){for(int n=0;n<N;n++)h.assertTrue(MineAccessSavedData.get(server).evidence().mark(new MineAccessEvidence.Cell("minecraft:overworld",at(n).asLong())).orElseThrow().player().equals(p.getUUID()),"Second JVM preserves genuine placement owner");start(h,p,mine);return;}
  for(int n=0;n<N;n++){var pos=at(n);h.assertTrue(level.getBlockState(pos).isAir()&&level.getBlockState(pos.below()).isAir(),"Private supplied test access never overwrites structures or valuable terrain");level.setBlock(pos.below(),Blocks.STONE.defaultBlockState(),18);place(h,p,pos,Items.COBBLESTONE_STAIRS,180);h.assertTrue(level.getBlockState(pos).getValue(StairBlock.FACING)==Direction.NORTH,"Actual native placement faces the descending route");}
  h.runAfterDelay(5,()->guard(h,()->{for(int n=0;n<N;n++)h.assertTrue(MineAccessSavedData.get(server).evidence().mark(new MineAccessEvidence.Cell("minecraft:overworld",at(n).asLong())).isPresent(),"Actual native successful placements, not test-injected evidence");teleport(p,19.3);move(p,19.5);teleport(p,.1);move(p,.3);teleport(p,19.3);teleport(p,.1);h.assertTrue(MineAccessSavedData.get(server).evidence().route(p.getUUID()).isEmpty(),"Native teleport and interrupted partial movement cannot fabricate a round trip");java.nio.file.Files.writeString(server.getWorldPath(LevelResource.ROOT).resolve("mine-access-built.txt"),"Private actual placement/teleport rejection checkpoint; no quest/progress injection");com.mojang.logging.LogUtils.getLogger().info("MINE_ACCESS_PENDING_PASSED:20actual native placed stairs/material debits/retained owners, actual teleport/partial movement refusal; original500XP remains, first JVM saves real supports");h.succeed();}));
 }
 static void corrupt(GameTestHelper h,ServerPlayer p)throws Exception{var level=p.serverLevel();var extra=ROOT.offset(-4,0,-5);h.assertTrue(level.getBlockState(extra).isAir()&&level.getBlockState(extra.below()).isAir(),"Private fault placement cells are empty");level.setBlock(extra.below(),Blocks.STONE.defaultBlockState(),18);place(h,p,extra,Items.STONE_BRICK_STAIRS,180);teleport(p,.1);h.runAfterDelay(5,()->guard(h,()->{move(p,.3);h.assertTrue(Math.abs(p.getZ()-(ROOT.getZ()+.3))<.001,"Malformed optional evidence cannot interrupt native accepted player movement");boolean refused=false;try{MineAccessSavedData.get(p.server);}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused&&CommerceService.store(p.server).professions(p.getUUID()).track(Profession.MINER).xp()==500&&!CommerceService.store(p.server).quarantined(),"Malformed proof refuses progression without resetting evidence or quarantining unrelated accounts");h.assertTrue(java.nio.file.Files.readString(p.server.getWorldPath(LevelResource.ROOT).resolve("data/kingdomsmp_mine_access_v1.dat")).startsWith("Intentional private"),"Corrupt evidence bytes remain available for matching recovery");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("MINE_ACCESS_CORRUPT_PASSED: malformed saved placement evidence grants no proof/XP and is not silently reset; actual native item placement consumes one physical input, actual movement packets still succeed, original500XP/accounts/native receipts preserved");h.succeed();}));}
 static void place(GameTestHelper h,ServerPlayer p,BlockPos pos,Item item,float yaw){var held=p.getMainHandItem().copy();BlacksmithRepairRuntime.near(p,pos);p.setYRot(yaw);p.setXRot(0);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(item));p.gameMode.useItemOn(p,p.serverLevel(),p.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos.below()).add(0,.5,0),Direction.UP,pos.below(),false));h.assertTrue(p.getMainHandItem().isEmpty()&&!p.serverLevel().getBlockState(pos).isAir(),"Actual permitted native item placement consumes input at "+pos);p.setItemInHand(InteractionHand.MAIN_HAND,held);}
 static double height(ServerPlayer p,double t){double x=ROOT.getX()+.5,z=ROOT.getZ()+t,max=-9999;int approx=ROOT.getY()-(int)Math.floor(t);for(int xx=(int)Math.floor(x-.3);xx<=(int)Math.floor(x+.3);xx++)for(int zz=(int)Math.floor(z-.3);zz<=(int)Math.floor(z+.3);zz++)for(int y=approx-2;y<=approx+2;y++){var pos=new BlockPos(xx,y,zz);for(var box:p.serverLevel().getBlockState(pos).getCollisionShape(p.serverLevel(),pos).toAabbs())if(xx+box.maxX>x-.3+1e-7&&xx+box.minX<x+.3-1e-7&&zz+box.maxZ>z-.3+1e-7&&zz+box.minZ<z+.3-1e-7)max=Math.max(max,y+box.maxY);}if(max<-999)throw new IllegalStateException("No actual native support at path step "+t);return max;}
 static void ack(ServerPlayer p)throws Exception{var field=p.connection.getClass().getDeclaredField("awaitingTeleport");field.setAccessible(true);p.connection.handleAcceptTeleportPacket(new ServerboundAcceptTeleportationPacket(field.getInt(p.connection)));}
 static void teleport(ServerPlayer p,double t)throws Exception{p.teleportTo(p.serverLevel(),ROOT.getX()+.5,height(p,t),ROOT.getZ()+t,Set.of(),0,0);p.serverLevel().getChunkSource().move(p);ack(p);}
 static void move(ServerPlayer p,double t){p.connection.handleMovePlayer(new ServerboundMovePlayerPacket.Pos(ROOT.getX()+.5,height(p,t),ROOT.getZ()+t,true));}
 static void start(GameTestHelper h,ServerPlayer p,com.mohymods.kingdomsmp.persistence.ConstructionStore.Project mine)throws Exception{teleport(p,.1);h.runAfterDelay(10,()->guard(h,()->walk(h,p,mine,0)));}
 static void walk(GameTestHelper h,ServerPlayer p,com.mohymods.kingdomsmp.persistence.ConstructionStore.Project mine,int step)throws Exception{
  int down=96;if(step>2*down){h.assertTrue(MineAccessSavedData.get(p.server).evidence().route(p.getUUID()).isPresent(),"Actual accepted native descent belowY0 and return creates proof");for(var block:ConstructionFoundations.blocks(mine))p.serverLevel().getChunk(mine.origin().offset(block.offset()));BlacksmithRepairRuntime.near(p,mine.origin().offset(BlueprintRegistry.get(mine.blueprint(),1).home()));ProfessionPremisesRuntimeTests.whenResidents(h,List.of(mine),()->guard(h,()->award(h,p,mine)));return;}
  double t=step<=down?.3+step*.2:.3+(2*down-step)*.2;move(p,t);h.assertTrue(Math.abs(p.getZ()-(ROOT.getZ()+t))<.001,"Vanilla server actually accepts each movement rather than test-setting position at step "+step+" actual="+p.position()+" target="+t);h.runAfterDelay(1,()->guard(h,()->walk(h,p,mine,step+1)));
 }
 static void award(GameTestHelper h,ServerPlayer p,com.mohymods.kingdomsmp.persistence.ConstructionStore.Project mine)throws Exception{CreateCraftRuntime.counter(p,mine);var q=ProfessionService.review(p,"quest:"+MineAccessService.QUEST);ProfessionService.confirm(p,q.nonce());h.assertTrue(CommerceService.store(p.server).professions(p.getUUID()).track(Profession.MINER).xp()==600,"Actual normal review awards descent100XP once");fixtures(h,p);var level=p.serverLevel();teleport(p,.1);var admin=ClaimRuntimeTests.vanillaPlayer(level,UUID.nameUUIDFromBytes("MineAccessWarden".getBytes(java.nio.charset.StandardCharsets.UTF_8)),"MineWarden");p.server.getPlayerList().op(admin.getGameProfile());admin.teleportTo(level,ROOT.getX()-2.5,ROOT.getY()+1,ROOT.getZ()+.2,Set.of(),0,0);level.getChunkSource().move(admin);var review=ProfessionInspectionService.review(admin,p,MineInspection.LIGHTING,ROOT,"Retained player mine route actual safe lighting and claim consent");ClaimRuntimeTests.ftbUnclaim(level,at(19));ClaimRuntimeTests.ftbClaim(admin,at(19));boolean denied=false;try{ProfessionInspectionService.confirm(admin,review);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied,"Deep end claim revocation beyond ordinary local snapshot refuses");ClaimRuntimeTests.ftbUnclaim(level,at(19));ClaimRuntimeTests.ftbClaim(p,at(19));review=ProfessionInspectionService.review(admin,p,MineInspection.LIGHTING,ROOT,"Retained player mine route actual safe lighting and claim consent");ProfessionInspectionService.confirm(admin,review);h.assertTrue(CommerceService.store(p.server).professions(p.getUUID()).track(Profession.MINER).xp()==700,"Actual sixteen native lights earn100XP");review=ProfessionInspectionService.review(admin,p,MineInspection.FINAL,ROOT,"Supported access functional equipment separate ore bins and consent");ProfessionInspectionService.confirm(admin,review);h.assertTrue(CommerceService.store(p.server).professions(p.getUUID()).track(Profession.MINER).xp()==800&&CommerceService.store(p.server).professions(p.getUUID()).rank(Profession.MINER,ProfessionService.quests())==ProfessionRank.JOURNEYMAN,"All8actual Apprentice objectives earn800XP/Journeyman without proof injection");p.server.getPlayerList().deop(admin.getGameProfile());CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("MINE_ACCESS_NATIVE_PASSED: actual native retained20stairs, real vanilla accepted descent/return packets/teleport refusal, canonical XP once,16supported native lights/two real native filled sorting bins/functional tool, deep FTB revocation refusal/confirmed inspections/all8earned800XP/Journeyman; private supplied terrain/materials only, no quest/XP/rank/route proof injection");h.succeed();}
 static void fixtures(GameTestHelper h,ServerPlayer p)throws Exception{var level=p.serverLevel();for(int n=0;n<16;n++){var lamp=at(n).east().above();h.assertTrue(level.getBlockState(lamp).isAir()&&level.getBlockState(lamp.below()).isAir(),"Private light fixtures use empty terrain only");level.setBlock(lamp.below(),Blocks.STONE.defaultBlockState(),18);place(h,p,lamp,Items.TORCH,0);}for(var pos:BlockPos.betweenClosed(ROOT.offset(-5,0,-3),ROOT.offset(-1,0,3))){h.assertTrue(level.getBlockState(pos).isAir(),"Private sorting floor never overwrites existing terrain");level.setBlock(pos,Blocks.STONE.defaultBlockState(),18);}for(int n=0;n<2;n++){var bin=ROOT.offset(-4+n*2,1,-2);place(h,p,bin,Items.BARREL,0);var physical=new ItemStack(n==0?Items.COAL:Items.RAW_IRON);int slot=p.getInventory().getFreeSlot();h.assertTrue(slot>=0,"Physical sorting inputs fit native inventory");p.getInventory().setItem(slot,physical);BlacksmithRepairRuntime.near(p,bin);p.openMenu((net.minecraft.world.MenuProvider)level.getBlockEntity(bin));var menu=p.containerMenu;int index=-1;for(int i=0;i<menu.slots.size();i++)if(menu.getSlot(i).container==p.getInventory()&&menu.getSlot(i).getContainerSlot()==slot)index=i;h.assertTrue(index>=0,"Native barrel exposes actual player inventory slot");menu.clicked(index,0,ClickType.QUICK_MOVE,p);h.assertTrue(p.getInventory().getItem(slot).isEmpty(),"Actual menu transfer stocks separate physical sorting input");p.closeContainer();}h.assertTrue(p.getInventory().add(new ItemStack(Items.IRON_PICKAXE)),"Explicit physical inspection tool fits; no profession evidence injected");}
 interface Step{void run()throws Exception;}static void guard(GameTestHelper h,Step s){try{s.run();}catch(Exception e){com.mojang.logging.LogUtils.getLogger().error("Native mine access fixture failed",e);h.fail(e.toString());}}
}
